import { html, raw } from 'hono/html';
import { helpHeroArt, stepIcons } from './help-art';
import { OFFICIAL_DOCS } from '../official-docs';
import { password, codeField } from './layout';
import { qrCodes } from './qr-art';
const loading = html`<p class="muted">Loading…</p>`;
export function memberBody(page:string,name:string,server:string,seerr='') {
 const heading = (title:string) => html`<div class="top"><h1>${title}</h1></div>`;
 switch(page) {
 case 'home': return html`<div class="top"><span data-self-avatar class="avatar-slot" aria-hidden="true"></span><h1>Welcome back, ${name}</h1><span class="sp"></span><a class="btn pri" href="${server}" target="_blank" rel="noopener noreferrer">Open Jellyfin</a></div><section class="card home-account" id="home-account" aria-labelledby="home-account-h" hidden></section><div class="home-tiles"><section class="card home-tile" id="week-card" aria-labelledby="week-h"><h3 id="week-h" class="cardh">This week</h3><div id="week-body"><p class="muted">Loading…</p></div></section><section class="card home-tile" id="qc-card" aria-labelledby="qc-h"><h3 id="qc-h" class="cardh">Sign a TV in</h3><form id="home-quickconnect" class="help-qc"><label for="home-qc-code">On the TV choose Quick Connect, then type the 6 digit code here.</label><div class="help-qc-row"><input class="field" id="home-qc-code" name="code" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" minlength="6" maxlength="6" placeholder="6 digit code" required><button class="btn pri">Connect</button></div><p class="muted help-qc-result" id="home-qc-result" role="status"></p></form></section></div><div class="home"><section class="card" style="padding:20px"><h2 style="font-size:20px">Pick up where you left off</h2><p class="muted">Synced from Jellyfin. Resume on any device.</p><div id="shelf" data-server="${server}">${loading}</div></section><div class="stack"><section class="card"><h3 class="cardh">Your requests<small>via Seerr</small></h3><ul class="list" id="home-requests"><li class="muted">Loading…</li></ul></section><section class="card surprise" aria-labelledby="surprise-h"><h3 class="cardh" id="surprise-h">Surprise me<small>one film and one show you have not seen</small></h3><div class="surprise-box"><div id="surprise-film" class="surprise-body" aria-live="polite"><p class="muted">Finding a film…</p></div><div id="surprise-tv" class="surprise-body" aria-live="polite"><p class="muted">Finding a show…</p></div></div></section></div></div><section class="card home-account" id="now-card" aria-labelledby="now-card-h" hidden><h2 id="now-card-h" class="home-h">Watching now</h2><ul class="now-list" id="now-card-list"></ul></section><section class="recent-section" id="upnext-line" aria-labelledby="upnext-title" hidden><h2 id="upnext-title">Up next</h2><div class="recent-shelf" id="upnext-shelf" tabindex="0" role="region" aria-label="Next episodes"></div></section><section class="recent-section" id="recent-line" aria-labelledby="recent-title" aria-busy="true"><h2 id="recent-title">Recently added</h2><p class="sr-only" role="status">Loading recently added titles…</p><div class="recent-shelf" aria-hidden="true">${Array.from({length:6},()=>html`<div class="discover-skeleton"><div class="poster"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div>`)}</div></section><section class="recent-section" id="popular-line" aria-labelledby="popular-title" hidden><h2 id="popular-title">Popular right now</h2><div class="recent-shelf popular-shelf" id="popular-shelf" tabindex="0" role="region" aria-label="Popular titles"></div></section><p class="faint" id="status-line" role="status"><span class="dot" aria-hidden="true"></span><span>No data yet</span> <a href="/status">View status</a></p>`;
 case 'discover': return html`${heading('Discover and request')}<div class="tools discover-toolbar"><div class="field discover-search"><svg class="i" viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input id="search" type="search" maxlength="100" aria-label="Search titles" aria-keyshortcuts="/" placeholder="Search films and TV"><button class="btn ghost" id="discover-clear" type="button" aria-label="Clear search" hidden>×</button></div><div class="tabs" role="group" aria-label="Show">${[['all','All'],['film','Films'],['tv','TV shows']].map(([k,l])=>html`<button class="${k==='all'?'btn pri':'btn'}" type="button" data-tab="${k}" aria-pressed="${k==='all'?'true':'false'}">${l}</button>`)}</div>${seerr?html`<a class="btn pri" style="margin-left:auto" href="${seerr}" target="_blank" rel="noopener noreferrer">Open Seerr</a>`:""}</div><p class="faint">Requests are handled by Seerr. You'll get its email when a title is ready.</p><p id="discover-results" class="faint" role="status" aria-live="polite" aria-atomic="true">Loading titles…</p><div id="catalogue" aria-busy="true"><div class="cat discover-grid" aria-hidden="true">${Array.from({length:8},()=>html`<div class="discover-skeleton"><div class="poster"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div>`)}</div></div><dialog id="discover-dialog" aria-labelledby="discover-title"><button class="btn" id="discover-close" type="button" autofocus>Close</button><div class="discover-detail"><div id="discover-art"></div><div><h2 id="discover-title"></h2><p class="muted" id="discover-meta"></p><p id="discover-overview"></p><p id="discover-state"></p><div id="discover-action"></div></div></div></dialog><section class="card requests-card"><h3 class="cardh">My requests<small>via Seerr</small></h3><p class="sr-only" id="requests-loading" role="status">Loading requests…</p><ul class="cat discover-grid request-grid" id="requests" aria-busy="true">${Array.from({length:5},()=>html`<li class="discover-skeleton" aria-hidden="true"><div class="poster"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></li>`)}</ul></section>`;
 case 'history': return html`<div class="top history-top"><h1 id="history-top" tabindex="-1">Watch history</h1><span class="sp"></span><div class="tabs" role="group" aria-label="History filter">${[['','All'],['film','Films'],['tv','TV shows']].map(([k,t])=>html`<button class="btn" data-kind="${k}" aria-pressed="${k===''?'true':'false'}">${t}</button>`)}</div></div><div class="history-periods" role="tablist" aria-label="Time period">${[['week','Week'],['month','Month'],['90d','90 days'],['year','Year'],['all','All time']].map(([k,t])=>html`<button class="btn" type="button" role="tab" data-range="${k}" aria-selected="${k==='month'?'true':'false'}">${t}</button>`)}</div><div class="split history-layout"><div class="stack history-main"><div id="history-list" data-server="${server}" class="stack" aria-live="polite" aria-busy="true">${loading}</div><nav id="history-pager" class="history-pager" aria-label="History pages" hidden></nav><p class="faint">Only you and admins can see your history. <button class="link" id="history-clear">Clear all history</button></p></div><aside class="stack history-side" aria-label="Watch estimates"><div id="history-stats" class="stack">${loading}</div><p class="faint">Estimated from what Jellyfin records</p></aside></div><dialog id="history-clear-dialog" aria-labelledby="history-clear-title"><h2 id="history-clear-title">Clear all history?</h2><p>This hides your history in Jellypass and clears resume points. Your watched status in Jellyfin stays the same.</p><div class="actions"><button class="btn" id="history-clear-cancel">Cancel</button><button class="btn danger" id="history-clear-confirm">Clear all history</button></div></dialog>`;
 case 'devices': return html`<div class="top"><h1>Devices and sign-ins</h1><span class="sp"></span><button class="btn danger" type="button" id="devices-signout">Sign out everywhere</button><a class="btn pri" href="/help#device-guide">Set up a device</a></div><div class="split devices-layout"><div class="stack"><section class="card map-card"><h2 class="cardh">Where you've signed in<small>Approximate, from IP address</small></h2><div id="map" role="region" aria-label="Map of recent sign-ins"></div><div class="map-caption"><p id="map-state" role="status">Loading map…</p><p class="muted">© OpenStreetMap contributors · Protomaps</p></div></section><section class="card"><h2 class="cardh">Recent sign-ins</h2><div id="signins" class="compact-list">${loading}</div></section></div><aside class="card"><h2 class="cardh">Recent devices<small class="num" id="device-count"></small></h2><ul class="list" id="device-list"><li>Loading…</li></ul><p class="device-note muted">Devices seen in your sign-in history.</p></aside></div><dialog id="not-me-dialog" aria-labelledby="not-me-title"><h2 id="not-me-title">Secure your account?</h2><p>This signs you out everywhere and resets your Jellyfin password to a random one. You'll need to reset it using your confirmed email, or ask an admin.</p><div class="actions"><button class="btn" id="not-me-cancel">Cancel</button><button class="btn danger" id="not-me-confirm">This wasn't me</button></div></dialog><link rel="stylesheet" href="/assets/vendor/maplibre.css"><script src="/assets/vendor/maplibre.js" defer></script><script src="/assets/vendor/pmtiles.js" defer></script>`;
 case 'account': return html`${heading('Account and security')}<div class="account-page stack"><div class="col">
 <section class="card account account-overview" id="account-overview" aria-labelledby="account-overview-title" aria-busy="true"><h2 id="account-overview-title">Your account</h2>
 <div class="account-identity"><span data-self-avatar class="avatar-slot" aria-hidden="true"></span><div class="grow"><div class="account-name"><b id="account-username">${name}</b><span class="tag" id="account-role" hidden>Administrator</span></div><div id="account-loading"><span class="sr-only" role="status">Loading your account…</span><div aria-hidden="true"><div class="skeleton-line"></div><div class="skeleton-line short"></div></div></div><p class="muted" id="account-unavailable" role="status" hidden>Overview unavailable right now</p></div></div>
 <dl class="account-facts" id="account-details" hidden><div><dt>Access level</dt><dd id="account-level"></dd></div><div><dt>Member since</dt><dd id="account-since"></dd></div><div><dt>Access</dt><dd class="num" id="account-expiry"></dd></div><div class="account-wide"><dt>Libraries you can watch</dt><dd><ul class="account-libs" id="account-libraries" aria-label="Libraries you can watch"></ul></dd></div></dl>
 <div class="account-section"><div class="row"><div class="grow"><b>Profile picture</b><p class="muted">Your picture comes from Jellyfin.</p></div><a class="btn" id="change-picture" data-server="${server}" href="${server.replace(/\/$/,'')+'/web/#/userprofile'}" target="_blank" rel="noopener noreferrer">Change picture in Jellyfin</a></div></div>
 </section><section class="card account" id="account-checklist" aria-labelledby="account-checklist-title"><h2 id="account-checklist-title">Security checklist</h2>
 <p class="account-nudge needs-email" id="account-email-nudge" hidden>Add a verified email so you can reset your password</p>
 <div class="account-section needs-email"><div class="row"><span class="account-dot" id="account-email-dot" aria-hidden="true"></span><div class="grow"><b>Contact email</b><p class="muted" id="contact-email">Loading…</p></div><span class="tag" id="email-state" role="status">Not verified</span><button class="btn" type="button" data-reveal="email-edit" aria-controls="email-edit" aria-expanded="false" aria-label="Change contact email">Change</button></div>
 <div id="email-edit" class="needs-email" hidden><form class="stack inline-form" id="email"><label class="lab" for="email-address">Email address</label><input class="field" id="email-address" type="email" autocomplete="email" required>${password('email-password','Current password')}<button class="btn">Send verification code</button></form><form class="stack inline-form" id="confirm-email" hidden>${codeField('email-code')}<button class="btn">Verify email</button></form></div></div>
 <div class="account-section"><div class="row"><span class="account-dot" aria-hidden="true"></span><div class="grow"><b>Password</b><span class="muted" id="account-password-changed"> · Loading…</span></div><button class="btn" type="button" data-reveal="change-password" aria-controls="change-password" aria-expanded="false" aria-label="Change password">Change</button></div><form class="stack inline-form" id="change-password" hidden>${password('current','Current Jellyfin password')}${password('next','New password',true)}<div class="meter" aria-hidden="true"><i id="password-strength"></i></div><button class="btn">Update password</button></form></div>
 <div class="row"><span class="account-dot" aria-hidden="true"></span><div class="grow"><b>Last sign-in</b><p class="muted" id="account-last-signin">Loading…</p></div><a class="btn" href="/devices">Review devices and sign-ins</a></div>
 <div class="row"><span class="account-dot" aria-hidden="true"></span><div class="grow"><b>Other browsers signed in</b><p class="muted num" id="account-other-sessions">Loading…</p></div><a class="btn" href="#account-signout">Manage</a></div></section>
 <section class="card account" id="twofa-card" aria-labelledby="twofa-title"><h2 id="twofa-title">Two-step sign-in</h2><p class="muted">Optional. Ask for a code from an authenticator app, or a passkey, after your password, so a leaked password is not enough to get in.</p>
 <div class="account-section" id="twofa"><p class="muted" id="twofa-note" role="status">Loading…</p>
 <ul id="twofa-passkeys" class="account-browsers" aria-label="Your passkeys"></ul>
 <div class="stack inline-form"><div class="row"><button class="btn" type="button" id="twofa-totp-start">Set up an authenticator app</button><button class="btn danger" type="button" id="twofa-totp-off" hidden>Remove authenticator app</button><button class="btn" type="button" id="twofa-passkey-add">Add a passkey</button><button class="btn" type="button" id="twofa-recovery" hidden>Make new recovery codes</button></div></div>
 <form class="stack inline-form" id="twofa-passkey-save" hidden><label class="lab" for="twofa-passkey-name">Name this passkey (optional)</label><input class="field" id="twofa-passkey-name" maxlength="40" placeholder="For example, my phone"><button class="btn pri">Save passkey</button></form>
 <form class="stack inline-form" id="twofa-totp-confirm" hidden><p class="muted">Scan this with an authenticator app (Google Authenticator, Microsoft Authenticator, 1Password, Authy and others), then enter the 6-digit code it shows.</p><img id="twofa-qr" alt="QR code for your authenticator app" width="190" height="190" hidden><p class="muted">Cannot scan? Enter this key instead: <b class="num" id="twofa-secret"></b> · <a id="twofa-uri" href="#">Open in an authenticator app</a></p><label class="lab" for="twofa-code">6-digit code</label><input class="field" id="twofa-code" inputmode="numeric" autocomplete="one-time-code" maxlength="8" required><button class="btn pri">Turn on</button></form>
 <div id="twofa-codes" class="stack" hidden><b>Your recovery codes</b><p class="muted">Keep these somewhere safe. Each one works once if you lose your phone or passkey, and they will not be shown again.</p><pre class="num" id="twofa-codes-list"></pre><div class="row"><button class="btn" type="button" id="twofa-codes-copy">Copy to clipboard</button><button class="btn" type="button" id="twofa-codes-download">Download as a file</button></div></div>
 <p class="err" id="twofa-error" role="alert"></p></div>
 </section>
 </div><div class="col"><section class="card account" id="account-options" aria-labelledby="account-options-title"><h2 id="account-options-title">Sign-in options</h2>
 <div class="row needs-email"><div class="grow"><b>Sign in with an emailed link</b><label class="block" for="account-magic">Let me sign in with a one-time link sent to my verified email, as well as my password</label><p class="muted" id="account-magic-note">Needs a verified email. Not available for admin accounts.</p></div><label class="switch-hit"><input id="account-magic" type="checkbox" role="switch" aria-describedby="account-magic-note" disabled><span class="switch-track" aria-hidden="true"></span></label></div><form class="inline-confirm" id="account-magic-confirm" hidden><label class="grow">Enter your password to turn this on<input class="field" type="password" id="account-magic-password" autocomplete="current-password" required></label><button class="btn pri">Turn on</button><button class="btn" type="button" id="account-magic-cancel">Cancel</button></form><p class="err" id="account-magic-error" role="alert"></p>
 <div class="row needs-email"><div class="grow"><b>Sign-in alerts</b><label class="block" for="account-alerts">Email me when someone signs in from somewhere new</label><p class="muted" id="account-alerts-note">Loading alert preference…</p></div><label class="switch-hit"><input id="account-alerts" type="checkbox" role="switch" aria-describedby="account-alerts-note" disabled><span class="switch-track" aria-hidden="true"></span></label></div><p class="err" id="account-alerts-error" role="alert"></p>
 </section>
 <section class="card account" id="account-signout" aria-labelledby="account-signout-heading"><h2 id="account-signout-heading">Sign out</h2><h3 id="account-browsers-title">Your browsers</h3><ul id="account-browsers" class="account-browsers" aria-labelledby="account-browsers-title" aria-busy="true"><li class="muted">Loading browsers…</li></ul>
 <div class="row"><div class="grow"><b>Other portal browsers</b><p class="muted" id="account-browser-note">Checking other browsers…</p></div><button class="btn" type="button" id="signout-others" aria-describedby="account-browser-note" disabled>Sign out other browsers</button></div>
 <div class="row"><div class="grow"><b>Jellyfin apps and TVs</b><p class="muted">Sign out your devices and other portal browsers.</p></div><button class="btn danger" type="button" id="signout-devices">Sign out of all my devices</button></div>
 <p class="err" id="account-signout-error" role="alert"></p><div class="row"><button class="link" data-signout>Sign out</button></div></section>
 <section class="card account" id="account-data" aria-labelledby="account-data-title"><h2 id="account-data-title">Your data</h2>
 <div class="row"><div class="grow"><b>Download my data</b><p class="muted">Everything Jellypass holds about you (profile, sign-ins, ratings and watch history) as one file.</p></div><a class="btn" href="/api/account/export" download>Download</a></div>
 <div class="row" id="delete-account-row"><div class="grow"><b>Delete my account</b><p class="muted">Removes your Jellyfin login, your requests profile and everything Jellypass holds. This cannot be undone.</p></div><button class="btn danger" type="button" id="delete-account">Delete my account</button></div></section>
 <section class="card account needs-email" aria-labelledby="account-emails-title"><h2 id="account-emails-title">Emails and reminders</h2>
 <div class="row"><label class="grow" for="reminders"><b>Warn me before access expires</b><span class="muted block">7 days ahead.</span></label><label class="switch-hit"><input id="reminders" type="checkbox" role="switch" aria-label="Warn me before access expires"><span class="switch-track" aria-hidden="true"></span></label></div>
 <div class="row"><div class="grow"><b>Request emails</b><p class="muted">Sent by Seerr when a title you asked for is ready. Add your email in your Seerr profile to get them.</p></div>${seerr?html`<a class="btn" href="${seerr}/profile/settings">Open Seerr</a>`:""}</div>
 <div class="row"><a href="/?tour=1">Replay the tour</a></div></section></div></div>
 <dialog id="account-signout-dialog" aria-labelledby="account-signout-title" aria-describedby="account-signout-description"><h2 id="account-signout-title">Sign out of all my devices?</h2><p id="account-signout-description">Every Jellyfin app and TV will need to sign in again. Other portal browsers will also be signed out. This browser stays signed in. Your password is not changed.</p><p class="err" id="account-dialog-error" role="alert"></p><div class="actions"><button class="btn" type="button" id="account-signout-cancel" autofocus>Cancel</button><button class="btn danger" type="button" id="account-signout-confirm">Sign out devices</button></div></dialog>
 <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description"><h2 id="delete-title">Delete your account?</h2><p id="delete-description">This removes your Jellyfin login, your requests profile and everything Jellypass holds about you. It cannot be undone. Type your username and password to confirm.</p><form id="delete-form" class="stack"><label class="lab" for="delete-confirm">Your username</label><input class="field" id="delete-confirm" autocomplete="off" required>${password('delete-password','Current password')}<p class="err" id="delete-error" role="alert"></p><div class="actions"><button class="btn" type="button" id="delete-cancel" autofocus>Cancel</button><button class="btn danger" id="delete-submit">Delete my account</button></div></form></dialog>
 <dialog id="twofa-confirm" aria-labelledby="twofa-confirm-title"><h2 id="twofa-confirm-title">Confirm it is you</h2><p id="twofa-confirm-text">Enter your current password to continue.</p><form id="twofa-confirm-form" class="stack">${password('twofa-confirm-password','Current password')}<div class="actions"><button class="btn" type="button" id="twofa-confirm-cancel">Cancel</button><button class="btn danger">Continue</button></div></form></dialog>
 <dialog id="alerts-dialog" aria-labelledby="alerts-title" aria-describedby="alerts-description"><h2 id="alerts-title">Turn off sign-in alerts?</h2><p id="alerts-description">Enter your current password to stop emails about sign-ins from somewhere new.</p><form id="alerts-form" class="stack"><label class="lab" for="alerts-password">Current password</label><input class="field" id="alerts-password" name="password" type="password" autocomplete="current-password" required autofocus aria-describedby="alerts-error"><p class="err" id="alerts-error" role="alert"></p><div class="actions"><button class="btn" type="button" id="alerts-cancel">Cancel</button><button class="btn" type="submit" id="alerts-confirm">Turn off alerts</button></div></form></dialog>`;
 case 'compare': return html`${heading('Compare')}<div class="compare-page stack"><section class="card pad stack" id="watching-now" aria-labelledby="now-h"><h2 id="now-h">Watching now</h2><ul class="now-list" id="now-list" aria-live="polite"><li class="muted">Checking…</li></ul></section><section class="card pad stack"><p class="muted">Pick up to four members who have comparing on. You will see simple totals side by side, like hours watched and favourite genres, and only the titles all of you have watched.</p><p class="muted" id="compare-hint" role="status"></p><div id="compare-people" class="compare-people" aria-live="polite"><p class="muted">Loading…</p></div></section><section class="card pad stack" id="compare-result" hidden aria-live="polite"></section></div>`;
 case 'preferences': return html`${heading('Settings')}<div class="prefs-page stack"><div class="col"><section class="card prefs" aria-labelledby="prefs-appearance"><h2 id="prefs-appearance">Appearance</h2><p class="muted">Saved in this browser only, so each device can look different.</p><fieldset class="theme-choices"><legend class="sr-only">Theme</legend><span class="theme-thumb" aria-hidden="true"></span>${[['system','Auto','<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>'],['light','Light','<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>'],['dark','Dark','<path d="M20 14.5A8 8 0 019.5 4a8 8 0 1010.5 10.5z"/>'],['oled','OLED','<rect x="7" y="2.5" width="10" height="19" rx="2.5"/><path d="M11 18.5h2"/>']].map(([v,t,icon])=>html`<label class="theme-option"><input type="radio" name="theme" value="${v}"><svg class="i" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${raw(icon)}</svg><b>${t}</b></label>`)}</fieldset><p class="muted" id="theme-desc" aria-live="polite"></p></section><section class="card prefs" aria-labelledby="prefs-display"><h2 id="prefs-display">Display</h2><div class="switch-row"><div><label for="pref-motion"><b>Reduce motion</b></label><p class="muted" id="pref-motion-help">Turns off animations and transitions on this device.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-motion" aria-describedby="pref-motion-help"></div></section><section class="card prefs" aria-labelledby="prefs-notify"><h2 id="prefs-notify">Notifications</h2><div class="switch-row needs-email"><div><label for="pref-alerts"><b>Sign-in alerts</b></label><p class="muted" id="pref-alerts-help">Email me when someone signs in from somewhere new, or my account is playing in two places at once. Off by default; needs a verified contact email.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-alerts" aria-describedby="pref-alerts-help" disabled></div><form class="inline-confirm" id="pref-alerts-confirm" hidden><label class="grow">Enter your password to turn alerts off<input class="field" type="password" id="pref-alerts-password" autocomplete="current-password" required></label><button class="btn danger">Turn off alerts</button><button class="btn" type="button" id="pref-alerts-cancel">Cancel</button></form><div class="switch-row"><div><label for="pref-reminders"><b>Expiry reminders</b></label><p class="muted" id="pref-reminders-help">Warn me 7 days before my access ends.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-reminders" aria-describedby="pref-reminders-help" disabled></div><div class="switch-row"><div><label for="pref-banner"><b>Show new places on Home</b></label><p class="muted" id="pref-banner-help">Show a notice on Home when someone signs in from somewhere new. No email needed.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-banner" aria-describedby="pref-banner-help" disabled></div><div class="switch-row needs-email"><div><label for="pref-weekly"><b>Weekly summary</b></label><p class="muted" id="pref-weekly-help">A Monday email with what you watched, what is new and when your access ends. Needs a verified contact email.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-weekly" aria-describedby="pref-weekly-help" disabled></div><div class="switch-row needs-email"><div><label for="pref-ready"><b>Request ready emails</b></label><p class="muted" id="pref-ready-help">Email me when a title I asked for is in Jellyfin. Needs a verified contact email.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-ready" aria-describedby="pref-ready-help" disabled></div><div class="switch-row" id="pref-push-row" hidden><div><label for="pref-push"><b>Push notices on this device</b></label><p class="muted" id="pref-push-help">Pop-ups for new sign-ins, playing in two places at once and finished requests. Works without an email address. Turn it on in each browser or phone you want them on.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-push" aria-describedby="pref-push-help" disabled></div><div class="row" id="pref-push-test-row" hidden><button class="btn" type="button" id="pref-push-test">Send a test notice</button></div><p class="err" id="pref-error" role="alert"></p><div class="row"><div class="grow"><b>Seerr emails</b><p class="muted">Seerr can also email you when a title is ready. Add your email in your Seerr profile for that.</p></div>${seerr?html`<a class="btn" href="${seerr}/profile/settings" target="_blank" rel="noopener noreferrer">Open Seerr</a>`:""}</div></section></div><div class="col"><section class="card prefs" aria-labelledby="prefs-compare"><h2 id="prefs-compare">Compare watch history</h2><div class="row"><div class="grow"><b>Compare with other members</b><p class="muted" id="pref-compare-help">On by default. It adds a Compare page to the menu. You can only compare with members who have it on too, and they see simple totals (hours watched, favourite genres and similar) and only the titles you have both watched, never the rest of your history. It also shows who is watching right now, and what, to other members who have turned it on. They see the same about you. Turn it off at any time and you disappear from other members’ Compare pages.</p></div><input class="toggle" type="checkbox" role="switch" id="pref-compare" aria-describedby="pref-compare-help" disabled></div></section><section class="card prefs" aria-labelledby="prefs-privacy"><h2 id="prefs-privacy">Privacy and security</h2><div class="row"><div class="grow"><b>Where you’re signed in</b><p class="muted">See every device and sign-in, and sign out any you don’t recognise.</p></div><a class="btn" href="/devices">Devices</a></div><div class="row"><div class="grow"><b>Password and sessions</b><p class="muted">Change your password or sign out of all your devices.</p></div><a class="btn" href="/account">Account</a></div><div class="row"><div class="grow"><b>Clear watch history</b><p class="muted">Remove what Jellypass shows on your Watch history page.</p></div><a class="btn" href="/history">Watch history</a></div></section><section class="card prefs" aria-labelledby="prefs-help"><h2 id="prefs-help">Help</h2><div class="row"><div class="grow"><b>Replay the welcome tour</b><p class="muted">A quick walk-through of how everything works.</p></div><a class="btn" href="/?tour=1">Replay tour</a></div><div class="row"><div class="grow"><b>Reset display settings</b><p class="muted">Go back to matching your device.</p></div><button class="btn" type="button" id="prefs-reset">Reset</button></div></section></div></div>`;
 case 'wrapped': return html`<div class="top wrapped-top"><h1>Your Wrapped</h1><span class="sp"></span><label class="wrapped-year">Year <select class="field" id="wrapped-year" aria-label="Year"></select></label></div><section class="wrapped" id="wrapped" aria-label="Your year in watching" tabindex="0" data-server="${server}"><p class="wrapped-loading">Putting your year together…</p></section><p class="faint wrapped-note">Estimated from what Jellyfin records: it keeps the last time you watched each title, so a rewatch counts once.</p>`;
 case 'status': return html`<div class="status-page">${heading('Status')}<div id="service-summary" class="status-banner" role="status" data-state="unknown"><span class="dot" aria-hidden="true"></span><div><h2 id="overall-state">No data yet</h2><p id="last-checked">Checking services…</p></div></div><section id="services" class="status-services" aria-label="Service health and monitoring history" aria-busy="true"><p class="sr-only">Loading service health…</p>${['Jellyfin','Requests','Jellypass','Email delivery'].map(label=>html`<article class="status-service status-skeleton" aria-hidden="true"><div class="status-service-head"><div class="status-service-name"><h3>${label}</h3><p class="status-placeholder"></p></div><div class="status-service-health"><span class="status-chip">Checking…</span><span class="status-placeholder"></span></div></div><div class="status-strip">${Array.from({length:90},()=>html`<span class="status-bar" data-state="unknown"></span>`)}</div><div class="status-strip-caption"><span>90 days ago</span><span>Today</span></div></article>`)}</section><div class="status-footnote"><div class="status-legend" aria-label="Monitoring key"><span data-state="healthy">Operational</span><span data-state="problem">Problem</span><span data-state="warning">Partial failure</span><span data-state="unknown">No data</span></div><p id="status-since">Monitoring history is loading…</p></div><section class="recent-incidents" aria-labelledby="incidents-title"><h2 id="incidents-title">Recent incidents</h2><div id="incidents" aria-busy="true"><p class="status-empty muted">Loading incident history…</p></div></section></div>`;
 default: return help(server);
 }
}
export const articles: Array<[string, string, string, string[]?, string?]> = [
 // [category, question, answer, optional steps, optional call to action as [label, link, message subject]]
 ['start','How do I start watching?','It takes a couple of minutes and you only do it once per device.',['Install the free Jellyfin app on your TV, phone or computer (see Pick your device above).','Choose Add server and type our server address exactly as shown at the top of this page.','Sign in with your Jellyfin username and password. On a TV, use Quick Connect instead.','Pick something and press play.'],'Choose your device|#clients'],
 ['start','What is Quick Connect?','A 6 digit code that links your TV or device to your account, so you never type a password with a remote.',['On the TV, choose Quick Connect. It shows a 6 digit code.','Type that code into the Connect my TV box at the top of this page, or approve it from Jellyfin on your phone (profile menu, then Quick Connect).'],'Connect my TV|#help-quickconnect'],
 ['start','What is Wrapped?','A yearly review of what you watched: top shows and films, hours watched and a few fun facts you can save or share.',undefined,'See my Wrapped|/wrapped'],
 ['start','Can I compare what I watch with friends?','Yes, if you both have it on. It is on by default, and you can switch it off in Settings at any time. When it is on, a Compare page appears in the menu. You see simple totals like hours watched and favourite genres, and only titles you have both watched, never the rest of anyone’s history. The same switch also shows who is watching right now, and what, but only between members who have turned it on.',undefined,'Open Settings|/settings'],
 ['devices','Which devices work?','Most smart TVs, Fire TV, Android TV, Apple TV, phones, tablets and any modern web browser.',undefined,'Pick your device|#clients'],
 ['devices','Video is blurry or keeps buffering','This is nearly always the connection, not the film.',['In the player, open settings and choose a lower quality (try 720p or Auto).','Move closer to your router, or try another network such as mobile data.','Check the server is healthy on the Status page.','Still bad? Tell us the title, the device and when it happened.'],'Check status|/status'],
 ['devices','The app says it can’t connect or “address unavailable”','Usually the server address has a small typo or the device has no internet.',['Copy the address from the top of this page and paste it in, rather than typing it. It must start with https:// and have nothing after .co.uk.','Check the device is online (try a website or another app).','Try the web version in a browser. If that works, reinstall or update the app.','Check Status in case the server is being worked on.'],'Check status|/status'],
 ['devices','Subtitles or audio are in the wrong language','Open the player’s audio or subtitles menu while it plays and choose another track. Some titles only have one language, which is a library issue rather than your device.',undefined,'Tell an admin which title|#help-message|Something is missing'],
 ['requests','How do I ask for something?','Use Discover and request. Seerr emails you when it is ready, which can take a few hours.',['Open Discover and search for the title.','Press Request on the film or show you want.','Watch for the email, or check Your requests on Home. Ready means it is in Jellyfin.'],'Open Discover|/discover'],
 ['requests','My request is stuck on pending','An admin approves requests. Most are approved within a day. Check Your requests on Home to see its state. If it has been over two days, message an admin.',undefined,'See my requests|/discover'],
 ['requests','Why can’t I request in 4K?','4K requests are limited to admins to keep storage and streaming smooth. Standard HD requests cover almost everything, and the HD and 4K tags on posters show what we already have.'],
 ['requests','What do the badges on posters mean?','The small coloured square is the UK BBFC age rating (U, PG, 12, 15, 18). HD or 4K shows the best quality we already have in the library.'],
 ['account','How do I change my password?','Open Account and security, then Change password. Forgot it? Use the reset link on the sign-in page and enter the emailed code.',undefined,'Go to Account|/account'],
 ['account',"I see a sign-in I don't recognise",'Press “This wasn’t me” on that sign-in. It signs you out everywhere and resets your Jellyfin password to a random one. Then reset it with your confirmed email, or ask an admin.',['Open Devices and sign-ins.','Find the sign-in you don’t recognise and press This wasn’t me.','Reset your password from the sign-in page using your emailed code.'],'Open Devices|/devices'],
 ['account','How do I get sign-in alerts?','Add and verify a contact email in Account and security, then turn on Sign-in alerts in Settings. We email you when someone signs in from a new place, and you can also show them on Home. Every alert has a This wasn\'t me button.',undefined,'Add my email|/account'],
 ['account','Does my access run out?','If your account has an end date we email you 7 days before. You can turn those reminders off in Settings. To extend your access, ask an admin.',undefined,'Open Settings|/settings'],
 ['account','Can I change how Jellypass looks?','Yes: Auto, Light, Dark or pure black OLED, saved on each device.',undefined,'Open Settings|/settings'],
 ['fix',"I can't sign in",'Check your username (it is not your email), then use Reset your password on the sign-in page. Still stuck? Ask an admin.',['Check your username and that Caps Lock is off.','Use Reset your password on the sign-in page and enter the emailed code.','If you have no verified email, message an admin.'],'Message an admin|#help-message|Can\'t sign in'],
 ['fix',"A show won't play",'Check Status, then try another device. If it only fails on one title, tell us which.',['Check the Status page.','Try the same title in a web browser or on another device.','If only that title fails, message an admin with its name and the episode.'],'Check status|/status'],
 ['fix','Something I want is missing from the library','Search for it in Discover. If we do not have it, Request it. If it is shown as In library but you cannot find it in Jellyfin, tell us.',undefined,'Open Discover|/discover']
];
const phoneApps = [
 { key: 'ios' as const, name: 'iPhone and iPad', store: 'App Store', label: 'Get JellyTV (recommended)', alt: ['Or the official Jellyfin app', 'https://apps.apple.com/us/app/jellyfin-mobile/id1480192618'] as [string, string] },
 { key: 'android' as const, name: 'Android phone and tablet', store: 'Google Play', label: 'Open Google Play', alt: undefined as [string, string] | undefined },
];
// Official stores only. Samsung and LG have no worldwide link, so those guides say where to look on the TV itself.
const tvGuides: Array<{ id: string; name: string; steps: string[]; links?: Array<[string, string]>; note?: string }> = [
 { id: 'samsung', name: 'Samsung TV', steps: ['Press Home on the remote and open Apps.', 'Choose the search (magnifier) icon and type Jellyfin.', 'Select Jellyfin, then Install, then Open.'], note: 'Not listed? Your TV may be too old. Use a Fire TV Stick, Chromecast with Google TV or Apple TV instead (see Another TV below).' },
 { id: 'lg', name: 'LG TV', steps: ['Press Home on the remote and open the LG Content Store.', 'Search for Jellyfin.', 'Select Jellyfin, then Install, then Launch.'], note: 'Not listed? Your TV may be too old. Use a streaming stick instead (see Another TV below).' },
 { id: 'androidtv', name: 'Android TV, Google TV and Chromecast with Google TV', steps: ['Open the Google Play Store on the TV (or use the search bar on Home).', 'Search for Jellyfin and choose Jellyfin for Android TV.', 'Select Install, then Open.'], links: [['Google Play listing', 'https://play.google.com/store/apps/details?id=org.jellyfin.androidtv']] },
 { id: 'firetv', name: 'Amazon Fire TV and Fire Stick', steps: ['Press Home and choose Find (the magnifier), or hold the voice button and say Jellyfin.', 'Select Jellyfin for Android TV.', 'Choose Get or Download, then Open.'], links: [['Amazon Appstore listing', 'https://www.amazon.com/gp/aw/d/B07TX7Z725']] },
 { id: 'appletv', name: 'Apple TV', steps: ['Open the App Store on the Apple TV.', 'Search for JellyTV.', 'Choose Get, then Open.'], links: [['JellyTV on the App Store', 'https://apps.apple.com/gb/app/jellytv/id6752357290']] },
 { id: 'roku', name: 'Roku', steps: ['Press Home, then choose Streaming Channels.', 'Choose Search Channels and type Jellyfin.', 'Select Add Channel, then Go to channel.'], links: [['Roku Channel Store listing', 'https://channelstore.roku.com/details/592369/jellyfin']] },
 { id: 'xbox', name: 'Xbox', steps: ['Open the Microsoft Store on the Xbox.', 'Search for Jellyfin.', 'Choose Get (or Install), then Launch.'], links: [['Microsoft Store listing', 'https://apps.microsoft.com/detail/9P2DRTG62QF8']] },
 { id: 'other', name: 'Another TV, or an older model', steps: ['Plug a Fire TV Stick, Chromecast with Google TV or Apple TV into the TV. They are cheap and work on almost any TV with an HDMI port.', 'Then follow the guide for that device above.', 'No stick? Open the web browser on the TV, if it has one, and go to our server address.'] },
];
const tvGuideHtml = (server: string) => html`${tvGuides.map(g => html`<details class="help-tv" id="${'tv-' + g.id}"><summary>${g.name}</summary><ol class="help-howto">${g.steps.map(t => html`<li>${t}</li>`)}${g.id === 'other' ? '' : html`<li>When it asks for a server, choose Add server and type <code>${server}</code>.</li><li>Choose Quick Connect. The TV shows a 6 digit code: type it into the Connect my TV box at the top of this page.</li>`}</ol>${g.note ? html`<p class="muted">${g.note}</p>` : ''}<div class="actions">${(g.links ?? []).map(([label, url]) => html`<a class="btn" href="${url}" target="_blank" rel="noopener noreferrer">${label} <span aria-hidden="true">↗</span></a>`)}<a class="btn pri" href="#help-quickconnect">Connect my TV</a><button type="button" class="btn" data-copy-server>Copy server address</button></div></details>`)}`;
const phoneAppsHtml = html`<div class="help-qr-grid">${phoneApps.map(a => html`<figure class="help-qr card"><svg class="help-qr-code" viewBox="${`-4 -4 ${qrCodes[a.key].size + 8} ${qrCodes[a.key].size + 8}`}" role="img" aria-label="${`QR code that opens the recommended Jellyfin app in the ${a.store}`}" shape-rendering="crispEdges"><rect x="-4" y="-4" width="${String(qrCodes[a.key].size + 8)}" height="${String(qrCodes[a.key].size + 8)}" fill="#fff"/><path d="${qrCodes[a.key].path}" fill="#000"/></svg><figcaption><b>${a.name}</b><span class="muted">${a.store}</span><a class="btn pri" href="${qrCodes[a.key].url}" target="_blank" rel="noopener noreferrer">${a.label} <span aria-hidden="true">↗</span></a>${a.alt ? html`<a class="btn" href="${a.alt[1]}" target="_blank" rel="noopener noreferrer">${a.alt[0]} <span aria-hidden="true">↗</span></a>` : ''}</figcaption></figure>`)}</div>`;
function help(server:string) { return html`<div class="top"><h1>Help</h1><span class="sp"></span><a class="btn" href="/?tour=1">Replay the tour</a></div>
<section class="help-hero card" aria-labelledby="help-hero-h"><div class="help-hero-copy"><p class="help-kicker">New here?</p><h2 id="help-hero-h">Start watching in a few minutes</h2><p class="muted">Install a free Jellyfin app on your TV, phone or computer, add our server address and sign in. That is all it takes.</p><div class="help-cta"><a class="btn pri" href="#clients">Choose your device</a><a class="btn" href="${server}" target="_blank" rel="noopener noreferrer">Open Jellyfin in your browser</a><a class="btn" href="/discover">Ask for a film or show</a></div></div><div class="help-hero-art">${helpHeroArt}</div></section>
<section class="help-quick" aria-labelledby="quick-h"><h2 id="quick-h">What do you need help with?</h2><div class="help-quick-grid">${[['Video won’t play or keeps buffering','buffering'],['I can’t sign in','sign in'],['The app can’t connect','connect'],['My request is stuck','pending'],['Change my password','password'],['Something looks wrong on my account','recognise']].map(([t,q])=>html`<button type="button" class="help-quick-btn" data-q="${q}">${t} <span aria-hidden="true">→</span></button>`)}</div></section>
<details class="help-sec help-steps" data-sec="steps" open><summary><h2 id="steps-h">Get watching in four steps</h2><span class="help-sec-sub">Install, add the server, sign in, play</span></summary><ol class="help-step-list">
<li class="card"><span class="help-step-num" aria-hidden="true">1</span>${raw(stepIcons.app)}<h3>Get the app</h3><p class="muted">Pick your device below and install the official Jellyfin app. On a computer you can also just use the web link above.</p></li>
<li class="card"><span class="help-step-num" aria-hidden="true">2</span>${raw(stepIcons.server)}<h3>Add our server</h3><p class="muted">When the app asks for a server address, type this exactly:</p><p class="help-url"><code id="help-server-url">${server}</code> <button type="button" class="btn" id="help-copy-url">Copy</button></p></li>
<li class="card"><span class="help-step-num" aria-hidden="true">3</span>${raw(stepIcons.signin)}<h3>Sign in</h3><p class="muted">Use your Jellyfin username and password, the same ones you use for this site. On a TV, choose <b>Quick Connect</b> instead and approve the 6 digit code from your signed-in phone or browser.</p><form id="help-quickconnect" class="help-qc"><label for="help-qc-code"><b>Got a code on your TV?</b> Type it here to sign it in:</label><div class="help-qc-row"><input class="field" id="help-qc-code" name="code" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" minlength="6" maxlength="6" placeholder="6 digit code" required><button class="btn pri">Connect my TV</button></div><p class="muted help-qc-result" id="help-qc-result" role="status"></p></form></li>
<li class="card"><span class="help-step-num" aria-hidden="true">4</span>${raw(stepIcons.watch)}<h3>Pick something to watch</h3><p class="muted">Can't find it? <a href="/discover">Ask for it</a> and you will get an email when it is ready.</p></li>
</ol></details>
<details class="help-sec help-phone card" id="phone-app" data-sec="phone" open><summary><h2 id="phone-h">Get the phone app</h2><span class="help-sec-sub">On a computer: scan a code with your phone camera. On a phone: tap a button.</span></summary><div class="help-sec-body">${phoneAppsHtml}<p class="muted">Once installed, open it, add our server address (<code>${server}</code>) and sign in. Prefer a different app, or a Fire tablet? See Pick your device below.</p></div></details>
<details class="help-sec help-tvs card" id="tv-guides" data-sec="tv"><summary><h2 id="tv-h">Set up a TV</h2><span class="help-sec-sub">Step-by-step for Samsung, LG, Android TV, Fire TV, Apple TV, Roku and Xbox</span></summary><div class="help-sec-body help-tv-list">${tvGuideHtml(server)}</div></details>
<details class="help-sec help-clients card" id="clients" data-sec="clients" open><summary><h2 id="clients-h">Pick your device</h2><span class="help-sec-sub">Official apps for TV, phone and computer</span></summary><div class="help-sec-body"><div class="top"><div><p class="muted">The official Jellyfin apps, taken from jellyfin.org. <span id="clients-updated">Loading the list…</span></p></div></div><div class="tabs help-filter" role="group" aria-label="Device type">${[['all','All devices'],['phone','Phone and tablet'],['tv','TV'],['computer','Computer'],['browser','Web browser']].map(([k,t])=>html`<button type="button" class="btn" data-device="${k}" aria-pressed="${k==='all'?'true':'false'}">${t}</button>`)}</div><div id="client-grid" class="help-client-grid" data-server="${server}" aria-live="polite" aria-busy="true">${loading}</div></div></details>
<details class="help-sec help-docs" data-sec="docs"><summary><h2 id="docs-h">Official Jellyfin guides</h2><span class="help-sec-sub">Deeper how-tos on jellyfin.org</span></summary><div class="help-docs-grid">${OFFICIAL_DOCS.map(d=>html`<a class="help-doc card" href="${d.url}" target="_blank" rel="noopener noreferrer"><b>${d.title}</b><span class="muted">${d.text}</span><span class="help-doc-go">Open on jellyfin.org <span aria-hidden="true">↗</span></span></a>`)}</div></details>
<div class="tools help-tools"><label class="sr-only" for="help-search">Search help</label><input class="field" id="help-search" type="search" placeholder="Search help, e.g. Quick Connect"><div class="help-expand"><button type="button" class="btn" id="help-expand">Expand all</button><button type="button" class="btn" id="help-collapse">Collapse all</button></div><div class="tabs">${[['all','All'],['start','Getting started'],['devices','Devices'],['requests','Requests'],['account','Account'],['fix','Troubleshooting']].map(([k,t])=>html`<button class="btn" data-category="${k}" aria-pressed="${k==='all'?'true':'false'}">${t}</button>`)}</div></div><div class="split help-layout"><div class="stack"><section class="card articles" id="articles">${articles.map(([cat,title,body,steps,cta])=>{const [label,href,subject]=(cta??'').split('|');return html`<details data-article="${cat}"><summary>${title}</summary><p class="muted">${body}</p>${steps?html`<ol class="help-howto">${steps.map(t=>html`<li>${t}</li>`)}</ol>`:''}${label?html`<a class="btn help-article-cta" href="${href}" ${subject?html`data-subject="${subject}"`:''}>${label} <span aria-hidden="true">→</span></a>`:''}</details>`;})}<p id="no-help" hidden>No answers match. Try fewer words, or <a href="#help-message">message an admin</a>.</p></section><section class="card pad stack" id="device-guide"><h2>Set up a device</h2><div class="tabs guide-tabs" role="group" aria-label="Device type">${['Smart TV','Phone','Fire TV / Android TV','Browser'].map((t,i)=>html`<button type="button" class="btn" data-guide="${String(i)}" aria-pressed="${i===0?'true':'false'}" aria-controls="guide-instructions">${t}</button>`)}</div><ol class="help-howto" id="guide-instructions"><li>Open your TV’s app store and search for Jellyfin.</li><li>Install and open it, then choose Add server.</li><li>Type the server address below.</li><li>Choose Quick Connect and type the code it shows into the box at the top of this page.</li></ol><p>Server address: <b id="guide-server">${server}</b> <button type="button" class="link" id="copy-server">Copy</button></p><a href="${server}" class="btn" target="_blank" rel="noopener noreferrer">Open Jellyfin</a></section></div><form id="help-message" class="card pad stack"><h2>Still stuck? Message an admin</h2><label class="lab" for="subject">What's it about?</label><select class="field" id="subject"><option>Can't sign in</option><option>Video won't play</option><option>Something is missing</option><option>Extend my access</option><option>Something else</option></select><label class="lab" for="message">Tell us what happened</label><textarea class="field" id="message" rows="5" required maxlength="5000" placeholder="What did you try, and what did you see?"></textarea><label><input id="diagnostics" type="checkbox"> Attach diagnostics: member name, recent device names and service status; no IP addresses.</label><button class="btn pri">Send message</button><p class="muted">Check <a href="/status">Status</a> first if lots of things are slow.</p></form></div><p class="muted help-credits">Approximate sign-in locations use GeoLite2 data created by <a href="https://www.maxmind.com" target="_blank" rel="noopener noreferrer">MaxMind</a>. Place names come from <a href="https://www.geonames.org" target="_blank" rel="noopener noreferrer">GeoNames</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>.</p>`; }
